#!/usr/bin/env python3
"""Checks that a pull request description follows .github/PULL_REQUEST_TEMPLATE.md.

Run by .github/workflows/pr-description-verification.yml. Reads the pull request from the event
payload at $GITHUB_EVENT_PATH. Every message it prints is a fixed string, never description text.

The stages are parse (parse_lines, find_sections), check (find_problems), and report (main).
"""

import json
import os
import re
import sys
from dataclasses import dataclass

# These must match .github/PULL_REQUEST_TEMPLATE.md exactly. Update both together.
TEMPLATE_HEADINGS = [
    'Motivation and Context', 'Modifications', 'Testing', 'Screenshots (if appropriate)',
    'Types of changes', 'Checklist', 'AI tools', 'License',
]
PROSE_SECTIONS = ['Motivation and Context', 'Modifications', 'Testing']
TYPE_SECTION = 'Types of changes'
REQUIRED_ATTESTATIONS = {
    'AI tools': [
        'I wrote this pull request description myself, not with an AI tool',
        'I have reviewed all changes in this pull request myself, including any generated by AI tools',
    ],
    'License': [
        'I confirm that this pull request can be released under the Apache 2 license',
    ],
}

MISSING_FIX = {
    'Motivation and Context': 'explain why the change is needed under it',
    'Modifications': 'describe the changes under it',
    'Testing': 'describe how you tested the change under it',
    'Types of changes': 'mark at least one box under it with [x]',
    'AI tools': 'check both statements under it',
    'License': 'check the statement under it',
}
EMPTY_FIX = {
    'Motivation and Context': 'Explain why the change is needed, below the template comments.',
    'Modifications': 'Describe the changes.',
    'Testing': 'Describe how you tested the change.',
}
HEADER = 'The pull request description does not follow .github/PULL_REQUEST_TEMPLATE.md:'
FOOTER = [
    'Edit the pull request description to fix these. The check runs again when the description is saved.',
    'See the "Automated Tools" section of CONTRIBUTING.md for why the AI tools statements are required.',
]

LINE_BREAK = re.compile(r'\r\n|\r|\n')
FENCE = re.compile(r' {0,3}(`{3,}|~{3,})')
HEADING = re.compile(r' {0,3}(#{1,6})(?=[ \t]|$)')
CHECKBOX = re.compile(r'[ \t]*[-*+][ \t]+\[([ xX])\]')
COMMENT_BLOCK = re.compile(r' {0,3}<!--')


def normalize(text):
    return ' '.join(text.split()).lower()


TEMPLATE_NAMES = {normalize(heading) for heading in TEMPLATE_HEADINGS}


@dataclass
class Line:
    text: str
    in_fence: bool = False
    level: int = 0
    name: str = ''


def fence_opener(raw):
    """Returns the marker of the code fence this line opens, or None."""
    match = FENCE.match(raw)
    if not match:
        return None
    marker = match.group(1)
    if marker[0] == '`' and '`' in raw[match.end():]:
        return None  # A backtick in the info string makes this inline code, not a fence.
    return marker


def closes_fence(raw, marker):
    match = FENCE.match(raw)
    return (match is not None
            and match.group(1)[0] == marker[0]
            and len(match.group(1)) >= len(marker)
            and raw[match.end():].strip() == '')


def comment_end(text, start):
    """Returns the index just past the comment opening at text[start], or -1 if it is unclosed."""
    after = start + len('<!--')
    for empty_comment_rest in ('>', '->'):
        if text.startswith(empty_comment_rest, after):
            return after + len(empty_comment_rest)
    end = text.find('-->', after)
    return -1 if end == -1 else end + len('-->')


def strip_inline_comments(text):
    """Removes comments that open and close within this line.

    A <!-- that does not close on its line is kept as text. GitHub would also hide the rest of the
    paragraph up to a later -->, but that can only hide text after content this line already has.
    """
    kept = []
    pos = 0
    while True:
        start = text.find('<!--', pos)
        if start == -1:
            break
        end = comment_end(text, start)
        if end == -1:
            break
        kept.append(text[pos:start])
        pos = end
    kept.append(text[pos:])
    return ''.join(kept)


def text_line(text):
    heading = HEADING.match(text)
    if not heading:
        return Line(text)
    name = normalize(text[heading.end():].strip().rstrip('#'))
    return Line(text, level=len(heading.group(1)), name=name)


def parse_lines(body):
    """Splits the body into lines, with HTML comments removed and fences and headings marked.

    A comment at the start of a line hides everything up to the next -->, across blank lines, or
    to the end of the body if unclosed, as GitHub renders it. Fenced code is never stripped.
    """
    lines = []
    fence = None
    in_comment = False
    for raw in LINE_BREAK.split(body):
        if fence:
            lines.append(Line(raw, in_fence=True))
            if closes_fence(raw, fence):
                fence = None
        elif in_comment:
            end = raw.find('-->')
            in_comment = end == -1
            lines.append(Line('' if in_comment else strip_inline_comments(raw[end + 3:])))
        elif marker := fence_opener(raw):
            fence = marker
            lines.append(Line(raw, in_fence=True))
        elif COMMENT_BLOCK.match(raw):
            end = comment_end(raw, raw.index('<!--'))
            in_comment = end == -1
            lines.append(Line('' if in_comment else strip_inline_comments(raw[end:])))
        else:
            lines.append(text_line(strip_inline_comments(raw)))
    return lines


def section_end(lines, start):
    """A section runs to the next template heading, or the next heading of the same or higher level."""
    for i in range(start + 1, len(lines)):
        line = lines[i]
        if line.level and (line.name in TEMPLATE_NAMES or line.level <= lines[start].level):
            return i
    return len(lines)


def find_sections(lines):
    """Maps each template heading's normalized name to the lines under its first occurrence."""
    sections = {}
    for i, line in enumerate(lines):
        if line.level and line.name in TEMPLATE_NAMES and line.name not in sections:
            sections[line.name] = lines[i + 1:section_end(lines, i)]
    return sections


def checked_items(section):
    """Returns the normalized text of each checked task-list item outside code fences."""
    items = []
    for line in section:
        box = None if line.in_fence or line.level else CHECKBOX.match(line.text)
        if box and box.group(1) != ' ':
            items.append(normalize(line.text[box.end():]))
    return items


def missing(name):
    return f'"{name}" is missing. Add a "## {name}" heading from the template and {MISSING_FIX[name]}.'


def find_problems(body):
    sections = find_sections(parse_lines(body or ''))
    problems = []

    for name in PROSE_SECTIONS:
        section = sections.get(normalize(name))
        if section is None:
            problems.append(missing(name))
        elif not any(line.text.strip() for line in section):
            problems.append(f'"{name}" is empty. {EMPTY_FIX[name]}')

    section = sections.get(normalize(TYPE_SECTION))
    if section is None:
        problems.append(missing(TYPE_SECTION))
    elif not checked_items(section):
        problems.append(f'"{TYPE_SECTION}" has no checked box. Mark at least one with [x].')

    for name, statements in REQUIRED_ATTESTATIONS.items():
        section = sections.get(normalize(name))
        if section is None:
            problems.append(missing(name))
            continue
        checked = checked_items(section)
        for statement in statements:
            if not any(item.startswith(normalize(statement)) for item in checked):
                problems.append(f'"{name}": "{statement}" is not checked.')

    return problems


def annotate_error(message):
    escaped = message.replace('%', '%25').replace('\r', '%0D').replace('\n', '%0A')
    print(f'::error::{escaped}')


def write_summary(problems):
    lines = [HEADER, ''] + [f'- {problem}' for problem in problems] + ['', FOOTER[0], '', FOOTER[1], '']
    with open(os.environ['GITHUB_STEP_SUMMARY'], 'a', encoding='utf-8') as summary:
        summary.write('\n'.join(lines))


def main():
    with open(os.environ['GITHUB_EVENT_PATH'], encoding='utf-8') as event_file:
        body = json.load(event_file)['pull_request'].get('body')
    problems = find_problems(body)
    if not problems:
        print('The pull request description follows .github/PULL_REQUEST_TEMPLATE.md.')
        return 0
    for problem in problems:
        annotate_error(problem)
    write_summary(problems)
    return 1


if __name__ == '__main__':
    sys.exit(main())
